   563→func TestMergeSearchResults_MirrorPlacementsDoNotDoubleCount(t *testing.T) {
   564→	t.Parallel()
   565→
   566→	// A US-homed repo with an EU mirror indexes the same content, so the
   567→	// fan-out queries both cells and each returns the SAME matches. Merged
   568→	// results dedupe by repo+path+line; the stats must dedupe too, or the
   569→	// summary reports "6 matches across 4 files in 2 repos" for 3 unique
   570→	// results (and falsely claims truncation). Regression guard for the
   571→	// mirror fan-out this trail introduced.
   572→	matches := []codesearch.Result{
   573→		{Repo: "acme/web", Path: "main.go", Line: 1, Column: 0, Score: 0.9},
   574→		{Repo: "acme/web", Path: "main.go", Line: 2, Column: 0, Score: 0.8},
   575→		{Repo: "acme/web", Path: "util.go", Line: 5, Column: 0, Score: 0.7},
   576→	}
   577→	cell := func(name, jur string) cellCallResult[*codesearch.SearchResponse] {
   578→		return cellCallResult[*codesearch.SearchResponse]{
   579→			group: cellGroup{cell: name, jurisdiction: jur},
   580→			value: &codesearch.SearchResponse{
   581→				Query:     "handleRequest",
   582→				Stats:     codesearch.Stats{TotalMatches: 3, TotalFiles: 2, ReposSearched: 1, DurationMs: 10},
   583→				RepoStats: []codesearch.RepoStats{{Repo: "acme/web", MatchCount: 3, FileCount: 2}},
   584→				Results:   matches,
   585→			},
   586→		}
   587→	}
   588→	results := []cellCallResult[*codesearch.SearchResponse]{
   589→		cell("aws-us-east-2", "us"),
   590→		cell(testCellEU, "eu"),
   591→	}
   592→
   593→	merged, err := mergeSearchResults(context.Background(), 0, results)
   594→	if err != nil {
   595→		t.Fatalf("unexpected error: %v", err)
   596→	}
   597→	if len(merged.Results) != 3 {
   598→		t.Fatalf("len(Results) = %d, want 3 (mirror duplicates removed)", len(merged.Results))
   599→	}
   600→	if merged.Stats.TotalMatches != 3 {
   601→		t.Errorf("TotalMatches = %d, want 3 (mirror must not double-count)", merged.Stats.TotalMatches)
   602→	}
   603→	if merged.Stats.TotalFiles != 2 {
   604→		t.Errorf("TotalFiles = %d, want 2 (mirror must not double-count)", merged.Stats.TotalFiles)
   605→	}
   606→	if merged.Stats.ReposSearched != 1 {
   607→		t.Errorf("ReposSearched = %d, want 1 (one logical repo across two cells)", merged.Stats.ReposSearched)
   608→	}
   609→	if merged.Stats.DurationMs != 10 {
   610→		t.Errorf("DurationMs = %v, want 10 (slowest cell preserved)", merged.Stats.DurationMs)
   611→	}
   612→	if len(merged.RepoStats) != 1 {
   613→		t.Fatalf("len(RepoStats) = %d, want 1 (deduped by repo)", len(merged.RepoStats))
   614→	}
   615→	if merged.RepoStats[0].MatchCount != 3 || merged.RepoStats[0].FileCount != 2 {
   616→		t.Errorf("RepoStats[0] = %+v, want representative {3,2} not summed {6,4}", merged.RepoStats[0])
   617→	}
   618→}
