		{"auth repo:gh/entirehq/cli", "auth", []string{"gh/entirehq/cli"}},
		{"repo:gh/a/b repo:et/c/d handleRequest", "handleRequest", []string{"gh/a/b", "et/c/d"}},
		{"repo:*", "", []string{"*"}},
