	checkpoint := newCheckpointSearchCmd().Example
	if !strings.Contains(checkpoint, "entire checkpoint search ") {
		t.Fatalf("checkpoint search examples must use the `entire checkpoint search` prefix:\n%s", checkpoint)
	}
}

