+	}
+
+	var buf bytes.Buffer
+	if err := writeSearchCompactJSON(&buf, resp, 0, 1); err != nil {
+		t.Fatalf("writeSearchCompactJSON returned error: %v", err)
+	}
+
+	output := buf.String()
+	// Identifiers, ranking, and files survive.
+	for _, want := range []string{
+		`"id": "a3b2c4d5e6f7"`,
+		`"type": "checkpoint"`,
